from django.conf import settings
from django.contrib.auth.backends import ModelBackend
from django.core.exceptions import ImproperlyConfigured
from django.db.models import get_model
from django.contrib.auth.models import User

class UserModelBackend(ModelBackend):
	def authenticate(self, username=None, password=None):
		try:
			user = self.user_class.objects.get(username=username)
			if user.check_password(password):
				return user
		except self.user_class.DoesNotExist:
			pass

		# If we get here, either we have a username that doesn't exist at all,
		# or it exists in the default User table, and we need to convert it.

		try:
			user = User.objects.get(username=username)
			if user.check_password(password):
				new_user = self.user_class(id=user.id, username=user.username, email=user.email, is_staff=user.is_staff, is_active=user.is_active)
				new_user.set_unusable_password()
				new_user.save()
				user.delete()
				return new_user
		except User.DoesNotExist:
			return None

	def get_user(self, user_id):
		try:
			return self.user_class.objects.get(pk=user_id)
		except self.user_class.DoesNotExist:
			return None

	@property
	def user_class(self):
		if not hasattr(self, '_user_class'):
			self._user_class = get_model(*settings.CUSTOM_USER_MODEL.split('.', 2))
			if not self._user_class:
				raise ImproperlyConfigured('Could not get custom user model')
		return self._user_class

