from django.conf import settings
from django.contrib.auth.backends import ModelBackend
from django.core.exceptions import ImproperlyConfigured
from django.db.models import get_model

class UserModelBackend(ModelBackend):
	def authenticate(self, username=None, password=None):
		try:
			user = self.user_class.objects.get(username=username)
			if user.check_password(password):
				return user
		except self.user_class.DoesNotExist:
			pass

		# If we get here, that means that we didn't find a matching user
		# in our custom User model. That could be because:
		# 1. The user never existed at all.
		# 2. The user existed before we switched to a custom User model, and
		#    so exists only in the vanilla Django user model.
		# In either case, we try to see if we can create a new custom User
		# based on a vanilla Django User. If we can, we create one. If we
		# can't, we just return None and the authenticate() call will fail.

		vanilla_user_model = get_model('auth', 'User')
		try:
			vanilla_user = vanilla_user_model.objects.get(username=username)
			if vanilla_user.check_password(password):
				# We found a matching vanilla user, and the password was valid.
				# So we create a custom User based on the vanilla one, and return it.
				user = self.user_class(username=vanilla_user.username)
				user.set_password(user.password) # hash the password correctly now we know the user class.
				user.save()

				# Now that we've created the custom user, we can delete the vanilla one.
				vanilla_user.delete()

				# And we return our new custom user, effectively completing the
				# authenticate() call successfully.
				return user
		except vanilla_user_model.DoesNotExist:
			return None

	def get_user(self, user_id):
		try:
			return self.user_class.objects.get(pk=user_id)
		except self.user_class.DoesNotExist:
			return None

	@property
	def user_class(self):
		if not hasattr(self, '_user_class'):
			self._user_class = get_model(*settings.CUSTOM_USER_MODEL.split('.', 2))
			if not self._user_class:
				raise ImproperlyConfigured('Could not get custom user model')
		return self._user_class

